<script setup>
import { ref } from "vue";
import FeeStatisticsChart from "@/components/FeeStatisticsChart.vue";
import Pies from "@/components/PieChart.vue";
import { getSssjInfo } from "@/api/all.js";

// 定义收费统计图表的标题和数据
const feeChartData = ref([
  {
    name: "同比",
    data: [2.0, 4.9, 7.0, 23.2, 25.6, 76.7, 135.6, 162.2, 32.6, 20.0, 6.4, 3.3],
    colorStart: "RGBA(255, 242, 39, 1)",
    colorEnd: "RGBA(255, 242, 39, .1)",
  },
  {
    name: "环比",
    data: [2.0, 4.9, 7.0, 23.2, 25.6, 76.7, 135.6, 162.2, 32.6, 20.0, 6.4, 3.3],
    colorStart: "rgba(39, 226, 250, 1)",
    colorEnd: "rgba(39, 226, 250, .1)",
  },
]);

// 定义闸阀状态数据
const valveStatusData = ref([]);

// 定义表格数据
const tableData = ref([]);

// 定义饼图数据
const economicData = ref([]);
const agriculturalData = ref([]);

// 调用接口获取实时数据
const getSssjInfoFn = async () => {
  try {
    const res = await getSssjInfo({});
    if (res.code === 200) {
      // 处理闸阀状态数据
      valveStatusData.value = res.result.valveStatusList.map(item => ({
        name: item.valveName,
        flow: item.flow,
        status: item.status
      }));
      
      // 处理表格数据
      tableData.value = res.result.liRealTimeDataVO.map(item => ({
        stationName: item.stationName,
        flow: item.pressure, // 注意：这里文档中是pressure，但界面上显示的是流量
        instant: item.pressure,
        reportTime: item.reportTime
      }));
      
      // 处理饼图数据
      economicData.value = res.result.waterSupply.map((item, index) => ({
        value: item.supplyVolume,
        name: item.region,
        itemStyle: { color: getColorByIndex(index, 'waterSupply') }
      }));
      
      agriculturalData.value = res.result.onlineDeviceQl.map((item, index) => ({
        value: parseFloat(item.proportion), // 将占比转换为数值
        name: item.deviceType,
        itemStyle: { color: getColorByIndex(index, 'onlineDeviceQl') }
      }));
    }
  } catch (error) {
    console.error("获取实时数据失败:", error);
  }
};

// 根据索引和数据类型获取颜色
const getColorByIndex = (index, type) => {
  const colors = {
    waterSupply: ['#F5472D', '#652BC5', '#25D4E4', '#2D6FF5', '#FADB51'],
    onlineDeviceQl: ['#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FFEAA7']
  };
  const colorArray = colors[type] || colors.waterSupply;
  return colorArray[index % colorArray.length];
};

// 组件挂载时调用接口
getSssjInfoFn();
</script>

