<template>
  <div class="custom-select" @click="toggleOptions">
    <div class="selected-value">{{ selectedOption?.label || placeholder }}</div>
    <div class="arrow" :class="{ 'arrow-up': isOpen }"></div>
    <div class="options" v-show="isOpen">
      <div
        class="option"
        v-for="option in options"
        :key="option.value"
        @click.stop="selectOption(option)"
      >
        {{ option.label }}
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: "CustomSelect",
  props: {
    options: {
      type: Array,
      default: () => [],
    },
    placeholder: {
      type: String,
      default: "请选择",
    },
  },
  data() {
    return {
      isOpen: false,
      selectedOption: null,
    };
  },
  methods: {
    toggleOptions() {
      this.isOpen = !this.isOpen;
    },
    selectOption(option) {
      this.selectedOption = option;
      this.isOpen = false;
      this.$emit("change", option);
    },
  },
  mounted() {
    // 点击外部关闭下拉框
    document.addEventListener("click", (e) => {
      if (!this.$el.contains(e.target)) {
        this.isOpen = false;
      }
    });
  },
};
</script>

