<template>
  <div class="itemBox">
    <div class="t" v-if="showTitle1">
      <span>{{ title1 }}</span>
    </div>
    <div class="chart-container">
      <div class="chart-item">
        <div class="chartBox" ref="chartLine1"></div>
      </div>
      <div class="chart-item">
        <div class="chartBox" ref="chartLine2"></div>
      </div>
    </div>
    <div class="t" v-if="showTitle2">
      <span>{{ title2 }}</span>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, watch } from "vue";
import * as echarts from "echarts";

export default {
  name: "PieChart",
  props: {
    title1: {
      type: String,
      default: "作物分布",
    },
    title2: {
      type: String,
      default: "作物分布",
    },
    showTitle1: {
      type: Boolean,
      default: true,
    },
    showTitle2: {
      type: Boolean,
      default: true,
    },
    economicData: {
      type: Array,
      default: () => [
      ]
    },
    agriculturalData: {
      type: Array,
      default: () => [
      ]
    },
  },
  setup(props) {
    let chartLine1 = ref(null);
    let chartLine2 = ref(null);

    const initChart = (chartRef, data) => {
      // 基于准备好的 DOM，初始化 echarts 实例
      const myChart = echarts.init(chartRef.value);

      // 指定图表的配置项和数据
      const option = {
        tooltip: {
          trigger: 'item'
        },
        series: [
          {
            name: '',
            type: 'pie',
            radius: ['60%', '70%'],
            avoidLabelOverlap: false,
            itemStyle: {
              shadowBlur: 20,
              shadowColor: (params) => {
                // 根据数据项颜色设置发光效果
                return params.data.itemStyle.color;
              },
              color: (params) => {
                // 创建渐变色
                const color = params.data.itemStyle.color;
                return {
                  type: 'linear',
                  x: 0,
                  y: 0,
                  x2: 0,
                  y2: 1,
                  colorStops: [
                    {
                      offset: 0,
                      color: color
                    },
                    {
                      offset: 1,
                      color: color + '80' // 添加透明度
                    }
                  ]
                };
              }
            },
            label: {
              show: true,
              position: 'center',
              fontSize: '14',
              fontWeight: 'normal',
              color: '#8FD4FF',
              formatter: (params) => {
                if (params.seriesIndex === 0) {
                  return props.title1;
                } else {
                  return props.title2;
                }
              }
            },
            emphasis: {
              label: {
                show: true,
                fontSize: '14',
                fontWeight: 'bold',
                color: '#1890ff',
              }
            },
            labelLine: {
              show: false
            },
            data: data
          }
        ]
      };

      // 使用刚指定的配置项和数据显示图表。
      myChart.setOption(option);
    };

    const initChartLine1 = () => {
      initChart(chartLine1, props.economicData);
    };

    const initChartLine2 = () => {
      initChart(chartLine2, props.agriculturalData);
    };

    onMounted(() => {
      initChartLine1();
      initChartLine2();
    });

    // 监听props变化，重新渲染图表
    watch(
      () => [props.economicData, props.agriculturalData],
      () => {
        initChartLine1();
        initChartLine2();
      },
      { deep: true }
    );

    return {
      chartLine1,
      chartLine2,
    };
  },
};
</script>

