<template>
  <div class="itemBox">
    <div class="t">
      <span>{{ title }}</span>
    </div>
    <div class="chartBox" ref="chartLine"></div>
  </div>
</template>

<script>
import { ref, onMounted, watch } from "vue";
import * as echarts from "echarts";

export default {
  name: 'TongbiHuanbiChart',
  props: {
    title: {
      type: String,
      default: '同比/环比'
    },
    chartData: {
      type: Array,
      default: () => []
    }
  },
  setup(props) {
    let chartLine = ref(null);
    
    const initChartLine = () => {
      // 基于准备好的 DOM，初始化 echarts 实例
      const myChart = echarts.init(chartLine.value);

      // 指定图表的配置项和数据
      const option = {
        grid: {
          top: "15%",
          left: "1%",
          right: "5%",
          bottom: "10%",
          // containLabel: true
        },
        tooltip: {
          trigger: "axis",
        },
        legend: {
          data: props.chartData.map(item => item.name),
          textStyle: { color: "#fff" },
          itemWidth: 30,
          itemHeight: 5,
          itemGap: 20,
          right: "0%",
        },
        xAxis: {
          type: "category",
          data: props.chartData.length > 0 ? props.chartData[0].data.map((_, index) => index + 1) : [],
          axisLabel: { color: "rgba(143, 212, 255, 1)", fontSize: "9px" },
        },
        yAxis: {
          type: "value",
          axisLabel: { show: false },
          axisTick: { show: false },
          axisLine: { show: false },
          splitLine: { show: false },
        },
        series: props.chartData.map(item => ({
          name: item.name,
          type: "line",
          data: item.data,
          smooth: true, //是否平滑曲线显示
          lineStyle: {
            color: item.lineColor,
            width: 3,
          },
          showSymbol: false,
          areaStyle: item.areaStyle ? {
            //区域填充样式
            normal: {
              color: new echarts.graphic.LinearGradient(
                0,
                0,
                0,
                1,
                [
                  {
                    offset: 0,
                    color: item.areaStyle.colorStart,
                  },
                  {
                    offset: 0.8,
                    color: item.areaStyle.colorEnd,
                  },
                ],
                false
              ),
              shadowColor: "rgba(0, 0, 0, 0.1)",
              shadowBlur: 10,
            },
          } : undefined,
        })),
      };

      // 使用刚指定的配置项和数据显示图表。
      myChart.setOption(option);
    };
    
    onMounted(() => {
      initChartLine();
    });
    
    // 监听props变化，重新渲染图表
    watch(() => props.chartData, () => {
      initChartLine();
    }, { deep: true });
    
    return {
      chartLine
    };
  }
}
</script>

