  <div class="viewBox">
    <div class="infoCards" :style="{ zoom: scale }">
      <div class="item">
        <div class="num">
          <img src="@/assets/img/cardIcon/icon_1.png" alt="" />
          <div class="numBox">
            <label>用水户</label>
            <span>{{ waterStats.userCount }}<em>户</em> </span>
            <p>{{ waterStats.userCountTrend }}% <img src="@/assets/img/cardIcon/top.png" alt="" /></p>
          </div>
        </div>
      </div>
      <div class="item">
        <div class="num">
          <img src="@/assets/img/cardIcon/icon_1.png" alt="" />
          <div class="numBox">
            <label>水费</label>
            <span>{{ waterStats.totalFee }}<em>元</em> </span>
            <p>{{ waterStats.totalFeeTrend }}% <img src="@/assets/img/cardIcon/top.png" alt="" /></p>
          </div>
        </div>
      </div>
    </div>
    <FeeStatisticsChart :title="'供水量'" :chartData="monthlySuppliesData"  :style="{ zoom: scale }"/>
    <Pies :title="'种植结构'" :economicData="economicData" :agriculturalData="agriculturalData" :style="{ zoom: scale }" />
    <FeeStatisticsChart :title="'需水量'" :chartData="monthlyDemandsData" :style="{ zoom: scale }" />
  </div>
</template>

<script setup>
import { ref, reactive } from "vue";
import FeeStatisticsChart from "@/components/FeeStatisticsChart.vue";
import Pies from "@/components/PieChart.vue";
import { getGqInfo } from "@/api/all";
// 定义收费统计图表的标题和数据
const feeChartTitle = ref("收费统计");
const monthlySuppliesData = ref([
  {
    name: "供水量",
    data: [],
    colorStart: "RGBA(255, 242, 39, 1)",
    colorEnd: "RGBA(255, 242, 39, .1)",
  }
]);

const monthlyDemandsData = ref([
  {
    name: "需水量",
    data: [],
    colorStart: "rgba(39, 226, 250, 1)",
    colorEnd: "rgba(39, 226, 250, .1)",
  }
]);

// 定义种植结构图表的数据
const economicData = ref([]);
const agriculturalData = ref([]);
const waterStats = ref({
  userCount: 0,
  userCountTrend: 0,
  totalFee: 0,
  totalFeeTrend: 0
});

const getGqInfoFn = async () => {
  const res = await getGqInfo({});
  console.log(res);
  if (res.success) {
    // 处理经济作物数据
    economicData.value = res.result.economicCrops.map(item => ({
      value: item.area,
      name: item.cropType,
      itemStyle: { color: '#F5472D' } // 这里可以设置不同的颜色
    }));
    
    // 处理农业作物数据
    agriculturalData.value = res.result.foodCrops.map(item => ({
      value: item.area,
      name: item.cropType,
      itemStyle: { color: '#652BC5' } // 这里可以设置不同的颜色
    }));
    
    // 处理用水户和水费数据
    waterStats.value = {
      userCount: res.result.waterStats.userCount,
      userCountTrend: res.result.waterStats.userCountTrend,
      totalFee: res.result.waterStats.totalFee,
      totalFeeTrend: res.result.waterStats.totalFeeTrend
    };
    
    // 处理月度供水量数据
    const suppliesData = res.result.monthlySupplies.map(item => item.supply);
    monthlySuppliesData.value[0].data = suppliesData;
    
    // 处理月度需水量数据
    const demandsData = res.result.monthlyDemands.map(item => item.demand);
    monthlyDemandsData.value[0].data = demandsData;
  }
};
const init = () => {
  setScale();
  window.addEventListener("resize", setScale);
};
let scale = ref(1);
const setScale = () => {
  let ww = window.innerWidth / 1920;
  let wh = window.innerHeight / 1080;
  scale.value = ww < wh ? ww : wh;
};
init();
getGqInfoFn();
</script>

