<template>
  <div class="leftNav" :style="{ zoom: scale }">
    <div class="nav">
      <div
        class="item"
        v-for="(item, index) in navItems"
        :key="index"
        @click="selectItem(index)"
        :class="{ active: selectedIndex === index }"
      >
        <div class="icon">
          <img :src="item.icon" alt="" />
        </div>
        <span>{{ item.text }}</span>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, defineEmits, onMounted } from "vue";

const navItems = [
  { icon: require("@/assets/img/navIcom/icon_1.png"), text: "灌区信息" },
  { icon: require("@/assets/img/navIcom/icon_2.png"), text: "种植结构" },
  { icon: require("@/assets/img/navIcom/icon_3.png"), text: "实时数据" },
  { icon: require("@/assets/img/navIcom/icon_4.png"), text: "官网概图" },
  { icon: require("@/assets/img/navIcom/icon_5.png"), text: "远程控制" },
  { icon: require("@/assets/img/navIcom/icon_6.png"), text: "水费信息" },
  { icon: require("@/assets/img/navIcom/icon_7.png"), text: "热力图" },
];

const selectedIndex = ref(null);

const emit = defineEmits(["item-selected"]);

const selectItem = (index) => {
  selectedIndex.value = index;
  // 触发自定义事件，将选中项的索引和数据传递给父组件
  emit("item-selected", { index, name: navItems[index].text });
};

onMounted(() => {
  init();
});
const init = () => {
  setScale();
  window.addEventListener("resize", setScale);
};
let scale = ref(1);
const setScale = () => {
  let ww = window.innerWidth / 1920;
  let wh = window.innerHeight / 1080;
  scale.value = ww < wh ? ww : wh;
};
</script>

