<template>
  <div class="itemBox">
    <div class="t" v-if="showTitle">
      <span>{{ title }}</span>
    </div>
    <div class="chart-container">
      <div class="chart-item">
        <div class="chartBox" ref="chartLine1"></div>
      </div>
    </div>
  </div>
</template>

<script>
import { ref, onMounted, watch } from "vue";
import * as echarts from "echarts";

export default {
  name: "PieChart",
  props: {
    title: {
      type: String,
      default: "作物分布",
    },
    showTitle: {
      type: Boolean,
      default: true,
    },
    economicData: {
      type: Array,
      default: () => [
        { value: 30, name: "茶叶", itemStyle: { color: "#F5472D" } },
        { value: 20, name: "小麦", itemStyle: { color: "#652BC5" } },
        { value: 15, name: "玉米", itemStyle: { color: "#25D4E4" } },
        { value: 25, name: "大豆", itemStyle: { color: "#2D6FF5" } },
        { value: 10, name: "棉花", itemStyle: { color: "#FADB51" } },
      ],
    },
  },
  setup(props) {
    let chartLine1 = ref(null);

    const initChart = (chartRef, data) => {
      // 基于准备好的 DOM，初始化 echarts 实例
      const myChart = echarts.init(chartRef.value);

      // 指定图表的配置项和数据
      const option = {
        tooltip: {
          trigger: "item",
        },
        series: [
          {
            name: "作物分布",
            type: "pie",
            radius: ["60%", "70%"],
            avoidLabelOverlap: false,
            itemStyle: {
              shadowBlur: 20,
              shadowColor: (params) => {
                // 根据数据项颜色设置发光效果
                return params.data.itemStyle.color;
              },
              color: (params) => {
                // 创建渐变色
                const color = params.data.itemStyle.color;
                return {
                  type: "linear",
                  x: 0,
                  y: 0,
                  x2: 0,
                  y2: 1,
                  colorStops: [
                    {
                      offset: 0,
                      color: color,
                    },
                    {
                      offset: 1,
                      color: color + "80", // 添加透明度
                    },
                  ],
                };
              },
            },
            label: {
              show: true,
              position: "center",
              fontSize: "14",
              fontWeight: "normal",
              color: "#8FD4FF",
              formatter: (params) => {
                if (params.seriesIndex === 0) {
                  return "经济作物";
                } else {
                  return "农业作物";
                }
              },
            },
            emphasis: {
              label: {
                show: true,
                fontSize: "14",
                fontWeight: "bold",
                color: "#1890ff",
                formatter: (params) => {
                  if (params.seriesIndex === 0) {
                    return "经济作物\n{d}%";
                  } else {
                    return "农业作物\n{d}%";
                  }
                },
              },
            },
            labelLine: {
              show: false,
            },
            data: data,
          },
        ],
      };

      // 使用刚指定的配置项和数据显示图表。
      myChart.setOption(option);
    };

    const initChartLine1 = () => {
      initChart(chartLine1, props.economicData);
    };

    onMounted(() => {
      initChartLine1();
    });

    // 监听props变化，重新渲染图表
    watch(
      () => [props.economicData, props.agriculturalData],
      () => {
        initChartLine1();
      },
      { deep: true }
    );

    return {
      chartLine1,
    };
  },
};
</script>

