<template>
  <div class="itemBox">
    <div class="t">
      <span>{{ title }}</span>
    </div>
    <div class="chartBox" ref="chartBar"></div>
  </div>
</template>

<script>
import { ref, onMounted, watch } from "vue";
import * as echarts from "echarts";

export default {
  name: "FeeStatisticsChart",
  props: {
    title: {
      type: String,
      default: "收费统计",
    },
    chartData: {
      type: Array,
      default: () => [],
    },
  },
  setup(props) {
    let chartBar = ref(null);

    const initChartBar = () => {
      // 基于准备好的 DOM，初始化 echarts 实例
      const myChart = echarts.init(chartBar.value);

      // 指定图表的配置项和数据
      const option = {
        grid: {
          top: "15%",
          left: "1%",
          right: "5%",
          bottom: "20%",
          // containLabel: true
        },
        tooltip: {
          trigger: "axis",
        },
        legend: {
          data: ["同比", "环比"],
          textStyle: { color: "#fff" },
          itemWidth: 30,
          itemHeight: 5,
          itemGap: 20,
          right: "0%",
        },
        xAxis: {
          type: "category",
          data:
            props.chartData.length > 0
              ? props.chartData[0].data.map((_, index) => index + 1)
              : [],
          axisLabel: { color: "rgba(143, 212, 255, 1)", fontSize: "9px" },
        },
        yAxis: {
          type: "value",
          axisLabel: { show: false },
          axisTick: { show: false },
          axisLine: { show: false },
          splitLine: { show: false },
        },
        series: props.chartData.map((item) => ({
          name: item.name,
          type: "bar",
          data: item.data,
          radius: ["2px", "2px", 0, 0], // 设置柱状图圆角，例如：左上、右上、右下、左下
          barWidth: 3, // 可选：设置柱子宽度
          itemStyle: {
            color: {
              type: "linear",
              x: 0, // 渐变色的起始位置
              y: 0, // 渐变色的起始位置
              x2: 0, // 渐变色的结束位置
              y2: 1, // 渐变色的结束位置
              colorStops: [
                { offset: 0, color: item.colorStart }, // 渐变起点颜色（顶部）
                { offset: 1, color: item.colorEnd }, // 渐变终点颜色（底部）
              ],
            },
          },
        })),
      };

      // 使用刚指定的配置项和数据显示图表。
      myChart.setOption(option);
    };

    onMounted(() => {
      initChartBar();
    });

    // 监听props变化，重新渲染图表
    watch(
      () => props.chartData,
      () => {
        initChartBar();
      },
      { deep: true }
    );

    return {
      chartBar,
    };
  },
};
</script>

