<script setup>
import { ref, onMounted } from "vue";
import FeeStatisticsChart from "@/components/FeeStatisticsChart.vue";
import { getGqXxInfo } from "@/api/all.js";

// 定义响应式数据
const irrigationData = ref({});
const alarmInfo = ref({});
const forecastInfo = ref({});
const irrigationAreaInfo = ref({});
const feeChartData = ref([
  {
    name: "同比",
    data: [2.0, 4.9, 7.0, 23.2, 25.6, 76.7, 135.6, 162.2, 32.6, 20.0, 6.4, 3.3],
    colorStart: "RGBA(255, 242, 39, 1)",
    colorEnd: "RGBA(255, 242, 39, .1)",
  },
  {
    name: "环比",
    data: [2.0, 4.9, 7.0, 23.2, 25.6, 76.7, 135.6, 162.2, 32.6, 20.0, 6.4, 3.3],
    colorStart: "rgba(39, 226, 250, 1)",
    colorEnd: "rgba(39, 226, 250, .1)",
  },
]);

// 获取灌区基本信息
const getGqXxInfoFn = async () => {
  try {
    const res = await getGqXxInfo({});
    if (res.success) {
      irrigationData.value = res.result.irrigationData || {};
      alarmInfo.value = res.result.alarmInfo || {};
      forecastInfo.value = res.result.forecastInfo || {};
      irrigationAreaInfo.value = res.result.irrigationAreaInfo || {};

      // 处理月供水量数据
      const monthlyWaterSupplyList = res.result.monthlyWaterSupplyList || [];
      const months = monthlyWaterSupplyList.map((item) => item.month);
      const waterSupplies = monthlyWaterSupplyList.map((item) => item.waterSupply);

      // 更新图表数据
      feeChartData.value[0].data = waterSupplies;
      feeChartData.value[1].data = waterSupplies;
    }
  } catch (error) {
    console.error("获取灌区基本信息失败:", error);
  }
};

// 组件挂载时获取数据
onMounted(() => {
  init();
  getGqXxInfoFn();
});
const init = () => {
  setScale();
  window.addEventListener("resize", setScale);
};
let scale = ref(1);
const setScale = () => {
  let ww = window.innerWidth / 1920;
  let wh = window.innerHeight / 1080;
  scale.value = ww < wh ? ww : wh;
};
</script>

